public class AppointmentDTO { private Long id; @NotBlank private String provider; @NotNull @Future private LocalDateTime appointmentAt; private Long centerId; @NotBlank private String reason; private String status; private String notes; public Long getId(){return id;} public void setId(Long x){id=x;} public String getProvider(){return provider;} public void setProvider(String x){provider=x;} public LocalDateTime getAppointmentAt(){return appointmentAt;} public void setAppointmentAt(LocalDateTime x){appointmentAt=x;} public Long getCenterId(){return centerId;} public void setCenterId(Long x){centerId=x;} public String getReason(){return reason;} public void setReason(String x){reason=x;} public String getStatus(){return status;} public void setStatus(String x){status=x;} public String getNotes(){return notes;} public void setNotes(String x){notes=x;} }
